from typing import List

class Solution:
    def matrixSum(self, nums: List[List[int]]) -> int:
        # Sort each row in descending order so that the largest elements come first
        for row in nums:
            row.sort(reverse=True)

        score = 0
        # Process column by column (i.e., take the largest from each row in each step)
        for col in range(len(nums[0])):
            current_max = 0
            # Find the maximum among the current elements of each row
            for row in nums:
                current_max = max(current_max, row[col])
            score += current_max

        return score
